import{c as a,M as e,h as r,k as d}from"./chunks/framework.MukIDqOt.js";const p=JSON.parse('{"title":"Glossário de Computação Gráfica","description":"Termos e conceitos essenciais de computação gráfica, modelagem e renderização.","frontmatter":{"title":"Glossário de Computação Gráfica","sidebar_label":"Glossário","description":"Termos e conceitos essenciais de computação gráfica, modelagem e renderização."},"headers":[],"relativePath":"glossario.md","filePath":"glossario.md","lastUpdated":1780580925000}'),o={name:"glossario.md"};function i(s,t,n,m,l,c){return e(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="🎨-glossario-de-computacao-grafica" tabindex="-1">🎨 Glossário de Computação Gráfica <a class="header-anchor" href="#🎨-glossario-de-computacao-grafica" aria-label="Permalink to “🎨 Glossário de Computação Gráfica”">​</a></h1><blockquote><p>Um glossáriOno estilo do FMHY/Piracy Glossary, foca*o nos conceitos mais importantes da Computação Gráfica, Renderização, Modelagem 3D, Engines de Jogos, OpenGL, Vulkan, DirectX, Blender, Unreal Engine e Graphics Programming.</p></blockquote><hr><h1 id="⭐-conceitos-fundamentais" tabindex="-1">⭐ Conceitos Fundamentais <a class="header-anchor" href="#⭐-conceitos-fundamentais" aria-label="Permalink to “⭐ Conceitos Fundamentais”">​</a></h1><table tabindex="0"><thead><tr><th>Termo</th><th>Descrição</th></tr></thead><tbody><tr><td>Rasterização</td><td>Processo que transforma objetos matemáticos (triângulos, linhas e polígonos) em pixels visíveis na tela. É a técnica usada pela maioria dos jogos modernos devido à sua velocidade.</td></tr><tr><td>Renderização</td><td>Processo completo de gerar uma imagem final a partir de uma cena 3D contendo objetos, materiais, luzes e câmeras.</td></tr><tr><td>Pipeline Gráfico</td><td>Sequência de etapas utilizadas pela GPU para transformar modelos 3D em pixels visíveis. Inclui Vertex Shader, Rasterização, Fragment Shader e Pós-processamento.</td></tr><tr><td>GPU</td><td>Unidade de Processamento Gráfico. Hardware especializado em executar milhões de cálculos paralelos necessários para renderização.</td></tr><tr><td>CPU</td><td>Processador principal do computador responsável pela lógica, física, IA e envio de comandos para a GPU.</td></tr><tr><td>Frame</td><td>Uma única imagem exibida na tela. Um jogo a 60 FPS gera 60 frames por segundo.</td></tr><tr><td>FPS</td><td>Frames por Segundo. Mede quantas imagens completas são renderizadas a cada segundo.</td></tr><tr><td>Latência</td><td>Tempo entre uma ação do usuário e sua visualização na tela.</td></tr><tr><td>Tempo de Frame</td><td>Tempo necessário para renderizar um único frame. Quanto menor, melhor.</td></tr></tbody></table><hr><h1 id="⭐-espacos-de-coordenadas" tabindex="-1">⭐ Espaços de Coordenadas <a class="header-anchor" href="#⭐-espacos-de-coordenadas" aria-label="Permalink to “⭐ Espaços de Coordenadas”">​</a></h1><table tabindex="0"><thead><tr><th>Termo</th><th>Descrição</th></tr></thead><tbody><tr><td>Model Space</td><td>Sistema de coordenadas local de um objeto. O modelo existe inicialmente nesse espaço.</td></tr><tr><td>World Space</td><td>Sistema de coordenadas global da cena onde todos os objetos são posicionados.</td></tr><tr><td>View Space</td><td>Espaço relativo à câmera. Após a transformação da câmera, tudo é calculado nesse sistema.</td></tr><tr><td>Clip Space</td><td>Espaço utilizado antes do recorte da geometria fora da câmera.</td></tr><tr><td>NDC</td><td>Normalized Device Coordinates. Sistema padronizado usado antes da conversão para pixels da tela.</td></tr><tr><td>Screen Space</td><td>Coordenadas finais em pixels na tela.</td></tr><tr><td>UV Space</td><td>Espaço bidimensional usado para mapear texturas em modelos 3D.</td></tr></tbody></table><hr><h1 id="⭐-geometria" tabindex="-1">⭐ Geometria <a class="header-anchor" href="#⭐-geometria" aria-label="Permalink to “⭐ Geometria”">​</a></h1><table tabindex="0"><thead><tr><th>Termo</th><th>Descrição</th></tr></thead><tbody><tr><td>Vértice</td><td>Ponto individual que compõe um objeto 3D.</td></tr><tr><td>Aresta</td><td>Linha que conecta dois vértices.</td></tr><tr><td>Face</td><td>Superfície formada por três ou mais vértices.</td></tr><tr><td>Triângulo</td><td>Unidade fundamental da renderização moderna. Quase toda geometria é convertida para triângulos.</td></tr><tr><td>Polygon Mesh</td><td>Estrutura composta por vértices, arestas e faces formando um modelo 3D.</td></tr><tr><td>Primitive</td><td>Forma geométrica básica processada pela GPU (triângulo, linha ou ponto).</td></tr><tr><td>Wireframe</td><td>Visualização mostrando apenas as arestas do modelo.</td></tr><tr><td>Tessellation</td><td>Processo de subdividir uma malha para aumentar sua complexidade.</td></tr><tr><td>Point Cloud</td><td>Conjunto de pontos sem faces ou arestas conectando-os.</td></tr><tr><td>Voxel</td><td>Equivalente tridimensional de um pixel.</td></tr></tbody></table><hr><h1 id="⭐-matrizes-e-vetores" tabindex="-1">⭐ Matrizes e Vetores <a class="header-anchor" href="#⭐-matrizes-e-vetores" aria-label="Permalink to “⭐ Matrizes e Vetores”">​</a></h1><table tabindex="0"><thead><tr><th>Termo</th><th>Descrição</th></tr></thead><tbody><tr><td>Vetor</td><td>Estrutura matemática usada para representar posição, direção ou velocidade.</td></tr><tr><td>Vetor Unitário</td><td>Vetor com comprimento exatamente igual a 1.</td></tr><tr><td>Vetor Normal</td><td>Vetor perpendicular a uma superfície. Fundamental para iluminação.</td></tr><tr><td>Matriz</td><td>Estrutura matemática usada para realizar transformações geométricas.</td></tr><tr><td>Matriz 4x4</td><td>Tipo mais comum utilizado para mover, girar e escalar objetos 3D.</td></tr><tr><td>Quaternion</td><td>Representação matemática de rotações que evita problemas dos ângulos de Euler.</td></tr><tr><td>Homogeneous Coordinates</td><td>Sistema que adiciona uma quarta coordenada (W) para facilitar transformações.</td></tr></tbody></table><hr><h1 id="⭐-transformacoes" tabindex="-1">⭐ Transformações <a class="header-anchor" href="#⭐-transformacoes" aria-label="Permalink to “⭐ Transformações”">​</a></h1><table tabindex="0"><thead><tr><th>Termo</th><th>Descrição</th></tr></thead><tbody><tr><td>Translation</td><td>Movimento de um objeto de uma posição para outra.</td></tr><tr><td>Rotation</td><td>Rotação de um objeto em torno de um eixo.</td></tr><tr><td>Scaling</td><td>Alteração do tamanho do objeto.</td></tr><tr><td>Transform Matrix</td><td>Matriz que combina posição, rotação e escala.</td></tr><tr><td>View Matrix</td><td>Matriz responsável por posicionar a câmera.</td></tr><tr><td>Projection Matrix</td><td>Matriz responsável por criar perspectiva.</td></tr></tbody></table><hr><h1 id="⭐-texturas" tabindex="-1">⭐ Texturas <a class="header-anchor" href="#⭐-texturas" aria-label="Permalink to “⭐ Texturas”">​</a></h1><table tabindex="0"><thead><tr><th>Termo</th><th>Descrição</th></tr></thead><tbody><tr><td>Texture</td><td>Imagem aplicada sobre um modelo para adicionar detalhes visuais.</td></tr><tr><td>Texture Map</td><td>Arquivo contendo os dados da textura.</td></tr><tr><td>Texel</td><td>Pixel individual de uma textura.</td></tr><tr><td>UV Mapping</td><td>Processo de associar partes de uma textura à superfície de um modelo.</td></tr><tr><td>UV Unwrapping</td><td>Processo de &quot;abrir&quot; um modelo 3D em 2D para texturização.</td></tr><tr><td>Texture Sampling</td><td>Leitura de texels pela GPU durante a renderização.</td></tr><tr><td>Texture Filtering</td><td>Técnicas que suavizam a aparência das texturas.</td></tr><tr><td>Texture Cache</td><td>Memória rápida da GPU para armazenar texels frequentemente utilizados.</td></tr><tr><td>Procedural Texture</td><td>Textura gerada matematicamente sem imagem pré-existente.</td></tr><tr><td>Volume Texture</td><td>Textura tridimensional contendo dados em volume.</td></tr></tbody></table><hr><h1 id="⭐-filtros-de-textura" tabindex="-1">⭐ Filtros de Textura <a class="header-anchor" href="#⭐-filtros-de-textura" aria-label="Permalink to “⭐ Filtros de Textura”">​</a></h1><table tabindex="0"><thead><tr><th>Termo</th><th>Descrição</th></tr></thead><tbody><tr><td>Nearest Neighbor</td><td>Usa apenas o texel mais próximo. Produz aparência pixelada.</td></tr><tr><td>Bilinear Filtering</td><td>Interpola quatro texels vizinhos para suavizar a imagem.</td></tr><tr><td>Trilinear Filtering</td><td>Interpola entre diferentes níveis de mipmaps.</td></tr><tr><td>Anisotropic Filtering</td><td>Mantém nitidez em superfícies vistas em ângulos inclinados.</td></tr><tr><td>Mipmap</td><td>Conjunto de versões reduzidas da mesma textura para evitar serrilhados.</td></tr></tbody></table><hr><h1 id="⭐-iluminacao" tabindex="-1">⭐ Iluminação <a class="header-anchor" href="#⭐-iluminacao" aria-label="Permalink to “⭐ Iluminação”">​</a></h1><table tabindex="0"><thead><tr><th>Termo</th><th>Descrição</th></tr></thead><tbody><tr><td>Lighting</td><td>Simulação do comportamento da luz em uma cena.</td></tr><tr><td>Ambient Light</td><td>Luz ambiente uniforme presente em toda a cena.</td></tr><tr><td>Diffuse Lighting</td><td>Luz refletida igualmente em todas as direções.</td></tr><tr><td>Specular Lighting</td><td>Reflexo brilhante dependente da posição do observador.</td></tr><tr><td>Global Illumination</td><td>Simulação das múltiplas reflexões de luz entre objetos.</td></tr><tr><td>Indirect Lighting</td><td>Luz que chega após refletir em outras superfícies.</td></tr><tr><td>Light Probe</td><td>Objeto usado para capturar informações de iluminação.</td></tr><tr><td>Shadow Mapping</td><td>Técnica para gerar sombras usando mapas de profundidade.</td></tr><tr><td>Shadow Map</td><td>Textura contendo profundidades vistas pela luz.</td></tr><tr><td>Shadow Volume</td><td>Técnica alternativa para criação de sombras.</td></tr><tr><td>HDR</td><td>Técnica que permite representar intensidades luminosas muito superiores às imagens tradicionais.</td></tr></tbody></table><hr><h1 id="⭐-materiais-e-pbr" tabindex="-1">⭐ Materiais e PBR <a class="header-anchor" href="#⭐-materiais-e-pbr" aria-label="Permalink to “⭐ Materiais e PBR”">​</a></h1><table tabindex="0"><thead><tr><th>Termo</th><th>Descrição</th></tr></thead><tbody><tr><td>Material</td><td>Conjunto de propriedades que define como uma superfície reage à luz.</td></tr><tr><td>PBR</td><td>Physically Based Rendering. Modelo moderno baseado em propriedades físicas reais dos materiais.</td></tr><tr><td>Albedo</td><td>Cor base do material sem influência da iluminação.</td></tr><tr><td>Roughness</td><td>Define o quão rugosa ou lisa uma superfície é.</td></tr><tr><td>Metallic</td><td>Determina se um material se comporta como metal ou não.</td></tr><tr><td>Normal Map</td><td>Textura que simula pequenos detalhes sem aumentar geometria.</td></tr><tr><td>Bump Map</td><td>Mapa de altura usado para criar ilusões de relevo.</td></tr><tr><td>Displacement Map</td><td>Move fisicamente os vértices para criar relevo real.</td></tr><tr><td>Ambient Occlusion (AO)</td><td>Aproxima regiões onde a luz ambiente é bloqueada.</td></tr><tr><td>BRDF</td><td>Modelo matemático que descreve como uma superfície reflete luz.</td></tr><tr><td>Fresnel</td><td>Fenômeno em que reflexos aumentam quando observados em ângulos rasantes.</td></tr></tbody></table><hr><h1 id="⭐-shaders" tabindex="-1">⭐ Shaders <a class="header-anchor" href="#⭐-shaders" aria-label="Permalink to “⭐ Shaders”">​</a></h1><table tabindex="0"><thead><tr><th>Termo</th><th>Descrição</th></tr></thead><tbody><tr><td>Shader</td><td>Programa executado diretamente na GPU.</td></tr><tr><td>Vertex Shader</td><td>Processa vértices individualmente.</td></tr><tr><td>Fragment Shader</td><td>Calcula a cor final dos pixels.</td></tr><tr><td>Geometry Shader</td><td>Pode criar ou modificar geometria durante a renderização.</td></tr><tr><td>Compute Shader</td><td>Shader voltado para computação geral na GPU.</td></tr><tr><td>Tessellation Shader</td><td>Controla subdivisões automáticas da malha.</td></tr><tr><td>Shader Language</td><td>Linguagem usada para escrever shaders, como GLSL ou HLSL.</td></tr></tbody></table><hr><h1 id="⭐-tecnicas-de-renderizacao" tabindex="-1">⭐ Técnicas de Renderização <a class="header-anchor" href="#⭐-tecnicas-de-renderizacao" aria-label="Permalink to “⭐ Técnicas de Renderização”">​</a></h1><table tabindex="0"><thead><tr><th>Termo</th><th>Descrição</th></tr></thead><tbody><tr><td>Forward Rendering</td><td>Método tradicional onde iluminação é calculada durante a renderização dos objetos.</td></tr><tr><td>Deferred Rendering</td><td>Renderização em múltiplas etapas, permitindo centenas de luzes eficientes.</td></tr><tr><td>Ray Casting</td><td>Técnica que lança raios sem simular reflexões complexas.</td></tr><tr><td>Ray Tracing</td><td>Simulação física dos caminhos da luz usando raios.</td></tr><tr><td>Path Tracing</td><td>Forma avançada de Ray Tracing usada em renderização realista.</td></tr><tr><td>Cone Tracing</td><td>Variante que utiliza cones para aproximar múltiplos raios.</td></tr><tr><td>Beam Tracing</td><td>Variante que utiliza feixes ao invés de raios individuais.</td></tr><tr><td>Offline Rendering</td><td>Renderização sem restrição de tempo.</td></tr><tr><td>Real-Time Rendering</td><td>Renderização em tempo real para jogos e aplicações interativas.</td></tr></tbody></table><hr><h1 id="⭐-otimizacoes" tabindex="-1">⭐ Otimizações <a class="header-anchor" href="#⭐-otimizacoes" aria-label="Permalink to “⭐ Otimizações”">​</a></h1><table tabindex="0"><thead><tr><th>Termo</th><th>Descrição</th></tr></thead><tbody><tr><td>Culling</td><td>Remoção de objetos que não precisam ser renderizados.</td></tr><tr><td>Frustum Culling</td><td>Remove objetos fora da visão da câmera.</td></tr><tr><td>Backface Culling</td><td>Remove faces voltadas para longe da câmera.</td></tr><tr><td>Occlusion Culling</td><td>Remove objetos escondidos atrás de outros.</td></tr><tr><td>LOD</td><td>Uso de versões simplificadas de objetos distantes.</td></tr><tr><td>Instancing</td><td>Renderização de múltiplas cópias usando a mesma geometria.</td></tr><tr><td>Batch Rendering</td><td>Agrupamento de múltiplos objetos em poucas chamadas para GPU.</td></tr><tr><td>Draw Call</td><td>Comando enviado pela CPU para renderizar algo.</td></tr><tr><td>State Change</td><td>Alteração de configurações da GPU que pode gerar perda de desempenho.</td></tr><tr><td>Baking</td><td>Pré-cálculo de informações pesadas para uso posterior.</td></tr></tbody></table><hr><h1 id="⭐-buffers" tabindex="-1">⭐ Buffers <a class="header-anchor" href="#⭐-buffers" aria-label="Permalink to “⭐ Buffers”">​</a></h1><table tabindex="0"><thead><tr><th>Termo</th><th>Descrição</th></tr></thead><tbody><tr><td>Framebuffer</td><td>Memória onde a imagem renderizada é armazenada.</td></tr><tr><td>Color Buffer</td><td>Armazena as cores dos pixels.</td></tr><tr><td>Depth Buffer</td><td>Armazena profundidades para determinar o que está visível.</td></tr><tr><td>Z Buffer</td><td>Implementação mais comum do Depth Buffer.</td></tr><tr><td>Stencil Buffer</td><td>Buffer auxiliar usado para máscaras e efeitos especiais.</td></tr><tr><td>Vertex Buffer</td><td>Armazena dados dos vértices.</td></tr><tr><td>Index Buffer</td><td>Armazena conexões entre vértices.</td></tr><tr><td>Command Buffer</td><td>Lista de comandos enviada à GPU.</td></tr><tr><td>G-Buffer</td><td>Conjunto de buffers utilizado em Deferred Rendering.</td></tr></tbody></table><hr><h1 id="⭐-apis-graficas" tabindex="-1">⭐ APIs Gráficas <a class="header-anchor" href="#⭐-apis-graficas" aria-label="Permalink to “⭐ APIs Gráficas”">​</a></h1><table tabindex="0"><thead><tr><th>Termo</th><th>Descrição</th></tr></thead><tbody><tr><td>OpenGL</td><td>API gráfica multiplataforma extremamente popular.</td></tr><tr><td>Vulkan</td><td>API moderna de baixo nível focada em desempenho.</td></tr><tr><td>Direct3D</td><td>API gráfica da Microsoft usada no Windows e Xbox.</td></tr><tr><td>Metal</td><td>API gráfica da Apple.</td></tr><tr><td>WebGL</td><td>Versão do OpenGL executada em navegadores.</td></tr><tr><td>WebGPU</td><td>Nova API gráfica para navegadores baseada em conceitos modernos.</td></tr></tbody></table><hr><h1 id="⭐-pos-processamento" tabindex="-1">⭐ Pós-processamento <a class="header-anchor" href="#⭐-pos-processamento" aria-label="Permalink to “⭐ Pós-processamento”">​</a></h1><table tabindex="0"><thead><tr><th>Termo</th><th>Descrição</th></tr></thead><tbody><tr><td>Post Processing</td><td>Efeitos aplicados após a renderização principal.</td></tr><tr><td>Bloom</td><td>Simula brilho intenso espalhando luz.</td></tr><tr><td>Tone Mapping</td><td>Conversão de HDR para telas comuns.</td></tr><tr><td>Motion Blur</td><td>Simula borrão causado por movimento.</td></tr><tr><td>Depth of Field</td><td>Simula foco de câmera real.</td></tr><tr><td>FXAA</td><td>Técnica rápida de anti-aliasing em pós-processamento.</td></tr><tr><td>SSAO</td><td>Aproxima oclusão ambiente usando apenas informações da tela.</td></tr><tr><td>Color Grading</td><td>Ajuste artístico das cores finais da imagem.</td></tr></tbody></table><hr><h1 id="⭐-anti-aliasing" tabindex="-1">⭐ Anti-Aliasing <a class="header-anchor" href="#⭐-anti-aliasing" aria-label="Permalink to “⭐ Anti-Aliasing”">​</a></h1><table tabindex="0"><thead><tr><th>Termo</th><th>Descrição</th></tr></thead><tbody><tr><td>Aliasing</td><td>Serrilhados causados pela representação discreta dos pixels.</td></tr><tr><td>Anti-Aliasing</td><td>Técnicas para suavizar bordas serrilhadas.</td></tr><tr><td>MSAA</td><td>Anti-aliasing baseado em múltiplas amostras por pixel.</td></tr><tr><td>FXAA</td><td>Método rápido baseado em pós-processamento.</td></tr><tr><td>TAA</td><td>Usa informações de frames anteriores para suavizar a imagem.</td></tr><tr><td>SSAA</td><td>Renderiza em resolução maior e reduz posteriormente.</td></tr></tbody></table><hr><h1 id="⭐-arquivos-e-formatos" tabindex="-1">⭐ Arquivos e Formatos <a class="header-anchor" href="#⭐-arquivos-e-formatos" aria-label="Permalink to “⭐ Arquivos e Formatos”">​</a></h1><table tabindex="0"><thead><tr><th>Termo</th><th>Descrição</th></tr></thead><tbody><tr><td>OBJ</td><td>Formato simples de modelos 3D.</td></tr><tr><td>FBX</td><td>Formato avançado com animações e esqueletos.</td></tr><tr><td>glTF</td><td>Formato moderno otimizado para aplicações em tempo real.</td></tr><tr><td>STL</td><td>Formato muito utilizado em impressão 3D.</td></tr><tr><td>PNG</td><td>Imagem sem perdas.</td></tr><tr><td>JPEG</td><td>Imagem comprimida com perdas.</td></tr><tr><td>EXR</td><td>Formato HDR utilizado em renderização profissional.</td></tr></tbody></table><hr><h1 id="⭐-termos-modernos" tabindex="-1">⭐ Termos Modernos <a class="header-anchor" href="#⭐-termos-modernos" aria-label="Permalink to “⭐ Termos Modernos”">​</a></h1><table tabindex="0"><thead><tr><th>Termo</th><th>Descrição</th></tr></thead><tbody><tr><td>VR</td><td>Virtual Reality. Ambiente completamente virtual.</td></tr><tr><td>AR</td><td>Augmented Reality. Conteúdo virtual sobreposto ao mundo real.</td></tr><tr><td>XR</td><td>Termo geral para VR, AR e tecnologias relacionadas.</td></tr><tr><td>Mesh Shader</td><td>Nova geração de shaders para substituir partes do pipeline tradicional.</td></tr><tr><td>Nanite</td><td>Tecnologia da Unreal Engine para renderizar bilhões de polígonos dinamicamente.</td></tr><tr><td>Lumen</td><td>Sistema de iluminação global em tempo real da Unreal Engine 5.</td></tr><tr><td>MegaTexture</td><td>Técnica para uso de texturas gigantes carregadas sob demanda.</td></tr><tr><td>Sparse Texture</td><td>Textura parcialmente carregada na memória para economizar VRAM.</td></tr><tr><td>Unified Memory</td><td>Arquitetura onde CPU e GPU compartilham a mesma memória.</td></tr></tbody></table><hr>',57)])])}const h=a(o,[["render",i]]);export{p as __pageData,h as default};
